package net.dogpoo.api.core.weaver.mapper;
import java.util.*;
import org.apache.ibatis.annotations.*;
@Mapper public interface WeaverNotificationMapper {
 String VISIBLE="n.user_id=#{user} AND (n.kind='subscription' OR (EXISTS(SELECT 1 FROM WEAVER_ACCOUNT_WORKSPACE w WHERE w.user_id=n.workspace_id AND w.archived_at IS NULL) AND ((n.kind='invite' AND EXISTS(SELECT 1 FROM WEAVER_WORKSPACE_INVITE i JOIN WEAVER_USER_ACCOUNT a ON a.email=i.email WHERE i.id=n.target_id AND a.id=#{user} AND i.status='pending' AND i.expires_at>UTC_TIMESTAMP(6))) OR (n.kind='comment' AND EXISTS(SELECT 1 FROM WEAVER_ACCOUNT_WORKSPACE w WHERE w.user_id=n.workspace_id AND (w.owner_id=#{user} OR EXISTS(SELECT 1 FROM WEAVER_WORKSPACE_MEMBER m WHERE m.workspace_id=w.user_id AND m.user_id=#{user}))) AND EXISTS(SELECT 1 FROM WEAVER_WORKSPACE_ITEM i WHERE i.user_id=n.workspace_id AND i.kind='list:elements' AND i.item_id=n.target_id AND i.deleted=FALSE)))))";
 @Select("SELECT n.id,n.kind,n.workspace_id AS workspaceId,n.target_id AS targetId,n.title,n.body,DATE_FORMAT(n.created_at,'%Y-%m-%dT%H:%i:%s.%fZ') AS createdAt,(n.read_at IS NOT NULL) AS isRead FROM WEAVER_ACCOUNT_NOTIFICATION n WHERE "+VISIBLE+" AND n.id<#{before} ORDER BY n.id DESC LIMIT 50") List<Map<String,Object>> list(@Param("user")String user,@Param("before")long before);
 @Select("SELECT COUNT(*) FROM WEAVER_ACCOUNT_NOTIFICATION n WHERE "+VISIBLE+" AND n.read_at IS NULL") long unread(String user);
 @Update("UPDATE WEAVER_ACCOUNT_NOTIFICATION SET read_at=COALESCE(read_at,UTC_TIMESTAMP(6)) WHERE user_id=#{user} AND id=#{id}") int read(@Param("user")String user,@Param("id")long id);
 @Update("UPDATE WEAVER_ACCOUNT_NOTIFICATION SET read_at=UTC_TIMESTAMP(6) WHERE user_id=#{user} AND read_at IS NULL AND id<=#{through}") int readAll(@Param("user")String user,@Param("through")long through);
 @Insert("INSERT INTO WEAVER_ACCOUNT_NOTIFICATION(user_id,event_key,kind,workspace_id,target_id,title,body,created_at) SELECT a.id,CONCAT('invite:',i.id),'invite',i.workspace_id,i.id,'워크스페이스 초대',CONCAT(w.name,'에 초대받았습니다.'),i.created_at FROM WEAVER_WORKSPACE_INVITE i JOIN WEAVER_USER_ACCOUNT a ON a.email=i.email JOIN WEAVER_ACCOUNT_WORKSPACE w ON w.user_id=i.workspace_id WHERE a.id=#{user} AND i.status='pending' AND i.expires_at>UTC_TIMESTAMP(6) AND w.archived_at IS NULL ON DUPLICATE KEY UPDATE id=WEAVER_ACCOUNT_NOTIFICATION.id") void invitations(String user);
 @Insert("INSERT INTO WEAVER_ACCOUNT_NOTIFICATION(user_id,event_key,kind,workspace_id,target_id,title,body) SELECT a.id,CONCAT('comment:',#{actor},':',#{request}),'comment',w.user_id,#{memo},'새 댓글',CONCAT(w.name,'의 생각에 새 댓글이 달렸습니다.') FROM WEAVER_ACCOUNT_WORKSPACE w JOIN WEAVER_USER_ACCOUNT a ON (a.id=w.owner_id OR EXISTS(SELECT 1 FROM WEAVER_WORKSPACE_MEMBER m WHERE m.workspace_id=w.user_id AND m.user_id=a.id)) WHERE w.user_id=#{workspace} AND a.id<>#{actor} ON DUPLICATE KEY UPDATE id=WEAVER_ACCOUNT_NOTIFICATION.id") void comment(@Param("workspace")String workspace,@Param("memo")String memo,@Param("actor")String actor,@Param("request")String request);
 @Insert("INSERT INTO WEAVER_ACCOUNT_NOTIFICATION(user_id,event_key,kind,title,body) VALUES(#{user},#{event},'subscription',#{title},#{body}) ON DUPLICATE KEY UPDATE id=WEAVER_ACCOUNT_NOTIFICATION.id") void subscription(@Param("user")String user,@Param("event")String event,@Param("title")String title,@Param("body")String body);
 @Insert("INSERT INTO WEAVER_ACCOUNT_NOTIFICATION(user_id,event_key,kind,title,body,created_at) SELECT user_id,CONCAT('expiry:',DATE_FORMAT(period_end,'%Y%m%d%H%i%s%f')),'subscription',IF(cancel_at_end,'구독 취소','구독 기한 만료'),'유료 이용 기간이 종료되어 Free 플랜으로 전환되었습니다.',period_end FROM WEAVER_ACCOUNT_SUBSCRIPTION WHERE user_id=#{user} AND period_end<=UTC_TIMESTAMP(6) ON DUPLICATE KEY UPDATE id=WEAVER_ACCOUNT_NOTIFICATION.id") void expired(String user);
}
